#!/usr/bin/env node
/**
 * Emits the server's list of audited collections: functions/_audit_collections.json,
 * from security/collections.json's `auditTrail: true` entries, and of audited
 * subcollections ('collection/subcollection', from `subcollections.<s>.auditTrail`,
 * including the comment thread a `commentThread` entry carries), with the
 * fields each one redacts (`auditRedact`), and the record search fields
 * the same trigger indexes (`search`). Cloud Functions
 * deploy only functions/, so the audit trail triggers (functions/audit_trail.js)
 * read this generated file, never the table.
 *
 * Run through security/generate.js (which writes it, and checks it with --check).
 */
'use strict';

const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const JSON_PATH = path.join(ROOT, 'functions', '_audit_collections.json');

/** The audited collections, sorted. */
function auditedCollections(table) {
  return Object.entries(table.collections)
    .filter(([, entry]) => entry.auditTrail === true)
    .map(([name]) => name)
    .sort();
}

/** The audited subcollections, 'collection/subcollection', sorted (table templates applied). */
function auditedSubcollections(table) {
  return Object.entries(table.collections)
    .flatMap(([name, entry]) => Object.entries(entry.subcollections || {})
      .filter(([, cfg]) => cfg && cfg.auditTrail === true)
      .map(([sub]) => `${name}/${sub}`))
    .sort();
}

/**
 * { collection: {apps, stewardRead} } for every collection carrying the
 * shared comment thread (`commentThread`): the comment moderation callable
 * (functions/comments_moderation.js) acts only on these, for their apps'
 * :admin tier and, where stewardRead, the steward groups' admins.
 */
function commentThreads(table) {
  return Object.fromEntries(Object.entries(table.collections)
    .filter(([, entry]) => entry.commentThread === true)
    .sort(([a], [b]) => (a < b ? -1 : 1))
    .map(([name, entry]) => [name, { apps: [...(entry.apps || [])], stewardRead: entry.stewardRead === true }]));
}

/**
 * collection -> the appId its audit events are recorded under, whatever the
 * doc's own appId says: the entry's auditAppId, or its one `apps` entry
 * (the rules' scope for a single-app collection, scopeOf). The events of a
 * collection with several apps take each doc's appId, as the rules do.
 */
function auditAppIds(table) {
  return Object.fromEntries(Object.entries(table.collections)
    .filter(([, entry]) => entry.auditTrail === true)
    .map(([name, entry]) => [name, entry.auditAppId || (Array.isArray(entry.apps) && entry.apps.length === 1 ? entry.apps[0] : null)])
    .filter(([, appId]) => typeof appId === 'string')
    .sort(([a], [b]) => a.localeCompare(b)));
}

/** collection -> the fields whose values its audit events never record (`auditRedact`). */
function auditRedactions(table) {
  return Object.fromEntries(Object.entries(table.collections)
    .filter(([, entry]) => entry.auditTrail === true && Array.isArray(entry.auditRedact) && entry.auditRedact.length)
    .map(([name, entry]) => [name, [...entry.auditRedact].sort()])
    .sort(([a], [b]) => a.localeCompare(b)));
}

/**
 * The audited collections whose docs steward groups read (`stewardRead`):
 * their history is reviewable by a steward group's admins too, the same
 * people who moderate their comment threads.
 */
function auditedStewardRead(table) {
  return Object.entries(table.collections)
    .filter(([, entry]) => entry.auditTrail === true && entry.stewardRead === true)
    .map(([name]) => name)
    .sort();
}

/**
 * collection -> its `search` block ({fields, digitFields?, hiddenWhen?}):
 * the audit trail's trigger keeps each doc's searchPrefixes current from
 * these fields (functions/_search_prefixes.js, plans/record-search).
 */
function searchConfigs(table) {
  return Object.fromEntries(Object.entries(table.collections)
    .filter(([, entry]) => entry.auditTrail === true && entry.search && Array.isArray(entry.search.fields))
    .map(([name, entry]) => [name, {
      fields: [...entry.search.fields],
      ...(entry.search.digitFields ? { digitFields: [...entry.search.digitFields] } : {}),
      ...(entry.search.hiddenWhen ? { hiddenWhen: [...entry.search.hiddenWhen] } : {}),
    }])
    .sort(([a], [b]) => a.localeCompare(b)));
}

function renderJson(table) {
  return `${JSON.stringify({
    comment: 'GENERATED by security/generate.js (security/generate_audit.js) from security/collections.json. Do not edit: change the table and run `node security/generate.js`.',
    collections: auditedCollections(table),
    subcollections: auditedSubcollections(table),
    commentThreads: commentThreads(table),
    appIds: auditAppIds(table),
    redact: auditRedactions(table),
    stewardRead: auditedStewardRead(table),
    groupIdFromDocId: Object.entries(table.collections)
      .filter(([, entry]) => entry.auditTrail === true && entry.auditGroupIdFromDocId === true)
      .map(([name]) => name)
      .sort(),
    search: searchConfigs(table),
  }, null, 2)}\n`;
}

/** Writes (or with --check, verifies) the server's list. */
function main(table, argv = []) {
  const next = renderJson(table);
  const current = fs.existsSync(JSON_PATH) ? fs.readFileSync(JSON_PATH, 'utf8') : null;
  if (argv.includes('--check')) {
    if (current !== next) {
      console.error(`${path.relative(ROOT, JSON_PATH)} is out of date with security/collections.json. Run \`node security/generate.js\` and commit the result.`);
      process.exitCode = 1;
    }
    return;
  }
  if (current !== next) {
    fs.writeFileSync(JSON_PATH, next);
    console.log(`${path.relative(ROOT, JSON_PATH)} regenerated.`);
  }
}

module.exports = { JSON_PATH, auditedCollections, searchConfigs, auditedSubcollections, commentThreads, auditAppIds, auditRedactions, auditedStewardRead, renderJson, main };
